"""spel_varMod (generated by netcdf_io.gen_spel_var_module): allocation from a descriptor,
compiled and run with gfortran."""

import shutil
import subprocess

import pytest

from spel.scripts.io.netcdf_io import gen_spel_var_module

pytestmark = pytest.mark.skipif(shutil.which("gfortran") is None, reason="needs gfortran")

PROGRAM = """
program t
   use iso_c_binding, only: c_associated, c_loc
   use spel_varMod
   implicit none
   type(spel_var_desc) :: d
   real(8), allocatable, target :: a(:, :)
   integer, pointer :: p(:)
   logical, pointer :: flag
   real(8), allocatable, target :: kept(:)

   ! bounds and fill from the descriptor
   d%name = 'a'; d%rank = 2; d%lb(1:2) = [-2, 0]; d%ub(1:2) = [3, 1]
   d%has_bounds = .true.; d%has_fill = .true.; d%fill_r8 = 1.d36
   call spel_var_allocate(a, d)
   print '(a,4i4)', 'a ', lbound(a), ubound(a)
   print '(a,l2)', 'a fill ', all(a == 1.d36)
   print '(a,l2)', 'a addr ', c_associated(d%addr, c_loc(a(-2, 0)))

   ! a pointer, without a fill
   d = spel_var_desc(name='p', rank=1, has_bounds=.true.)
   d%lb(1) = 5; d%ub(1) = 7
   nullify (p)
   call spel_var_allocate(p, d)
   print '(a,2i4)', 'p ', lbound(p), ubound(p)

   ! a logical pointer scalar, filled
   d = spel_var_desc(name='flag', rank=0, has_bounds=.true., has_fill=.true., fill_int=1)
   nullify (flag)
   call spel_var_allocate(flag, d)
   print '(a,l2)', 'flag ', flag

   ! already allocated: left as it is, the descriptor learns its bounds
   allocate (kept(10:12)); kept = 3.d0
   d = spel_var_desc(name='kept')
   call spel_var_allocate(kept, d)
   print '(a,3i4,l2)', 'kept ', d%rank, d%lb(1), d%ub(1), all(kept == 3.d0)

   ! no bounds: stops, naming the variable
   deallocate (kept)
   d = spel_var_desc(name='nobounds')
   call spel_var_allocate(kept, d)
end program t
"""


def test_spel_var_allocate(tmp_path):
    (tmp_path / "spel_varMod.F90").write_text(gen_spel_var_module())
    (tmp_path / "t.f90").write_text(PROGRAM)
    res = subprocess.run(["gfortran", "-std=f2008", "spel_varMod.F90", "t.f90", "-o", "t"], cwd=tmp_path,
                         capture_output=True, text=True)
    assert res.returncode == 0, res.stderr
    run = subprocess.run(["./t"], cwd=tmp_path, capture_output=True, text=True)
    lines = [ln.split() for ln in run.stdout.splitlines()]
    assert lines[0] == ["a", "-2", "0", "3", "1"]
    assert lines[1] == ["a", "fill", "T"] and lines[2] == ["a", "addr", "T"]
    assert lines[3] == ["p", "5", "7"]
    assert lines[4] == ["flag", "T"]
    assert lines[5] == ["kept", "1", "10", "12", "T"]
    assert run.returncode != 0 and "no bounds for nobounds" in run.stdout + run.stderr
